function demoMain(idx,label){
  var graphs=[{app:["ui","db"],ui:["util"],db:["util"],util:[]},{srv:["auth","cache"],auth:["db"],cache:[],db:[]},{cli:["core"],core:["net","fs"],net:[],fs:[]}];
  var g=graphs[idx%graphs.length]; var order=[]; var seen={};
  function visit(n){if(seen[n])return;seen[n]=1;(g[n]||[]).forEach(visit);order.push(n);}
  Object.keys(g).forEach(visit);
  var edges=0;for(var k in g)edges+=g[k].length;
  return "["+label+"] modules="+Object.keys(g).length+" edges="+edges+" build-order="+order.join(">");
}

